SELECT store_id, DATE_TRUNC('MONTH', last_restock) AS activity_month, DATE_TRUNC('YEAR', last_restock) AS year_start, STDDEV_SAMP(quantity) AS quantity_stddev, AVG(quantity) AS avg_quantity, RANK() OVER (PARTITION BY store_id ORDER BY AVG(quantity) DESC) AS avg_quantity_rank FROM inventory GROUP BY store_id, DATE_TRUNC('MONTH', last_restock), DATE_TRUNC('YEAR', last_restock) ORDER BY avg_quantity DESC
